class Cat {
    String name;

    Cat(String name) {
        this.name = name;
    }
}

public class Main {
    static Cat 养一只猫() {
        Cat 屋里那只 = new Cat("{n}");
        return 屋里那只;
    }

    public static void main(String[] args) {
        Cat 外面拿着的 = 养一只猫();
        System.out.println("外面拿着的：" + 外面拿着的.name);
    }
}
